-- Email sequence tables for 3-email Airbnb host campaign

CREATE TABLE IF NOT EXISTS email_sequence_templates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  sequence_name VARCHAR(100) NOT NULL,
  email_number INT NOT NULL,         -- 1, 2, 3
  subject TEXT NOT NULL,
  html_content TEXT NOT NULL,
  delay_days INT DEFAULT 0,          -- days after previous email
  created_at TIMESTAMP DEFAULT NOW(),
  UNIQUE(sequence_name, email_number)
);

CREATE TABLE IF NOT EXISTS email_sequence_enrollments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_email TEXT NOT NULL,
  recipient_name TEXT,
  sequence_name VARCHAR(100) NOT NULL DEFAULT 'airbnb-host',
  next_email_number INT DEFAULT 1,   -- which email to send next
  status VARCHAR(50) DEFAULT 'active', -- active | completed | unsubscribed
  last_sent_at TIMESTAMP,
  next_send_at TIMESTAMP DEFAULT NOW(),
  created_at TIMESTAMP DEFAULT NOW(),
  UNIQUE(recipient_email, sequence_name)
);

CREATE INDEX IF NOT EXISTS idx_enrollments_next_send ON email_sequence_enrollments(next_send_at, status);

